## Graduation: Your XIOM Journey

### The Levels You Conquered

```xiom
enum Level {
  L0; L1; L2; L3; L4; L5; L6; L7; L8;
}

type LevelSummary {
  level: Level;
  name: Str;
  lessons: Int;
  highlights: Vec[Str];
}

fn build_journey() -> Vec[LevelSummary] {
  let mut journey: Vec[LevelSummary] = Vec[LevelSummary].new();

  let mut l0_highs: Vec[Str] = Vec[Str].new();
  l0_highs.push("Hello World"); l0_highs.push("Variables"); l0_highs.push("Input/Output");
  journey.push(LevelSummary{ level: Level.L0, name: "Foundations", lessons: 40, highlights: l0_highs });

  let mut l1_highs: Vec[Str] = Vec[Str].new();
  l1_highs.push("Conditionals"); l1_highs.push("Type System"); l1_highs.push("Simple Logic");
  journey.push(LevelSummary{ level: Level.L1, name: "Control Flow", lessons: 40, highlights: l1_highs });

  let mut l2_highs: Vec[Str] = Vec[Str].new();
  l2_highs.push("Loops"); l2_highs.push("Functions"); l2_highs.push("Scope");
  journey.push(LevelSummary{ level: Level.L2, name: "Iteration & Functions", lessons: 40, highlights: l2_highs });

  let mut l3_highs: Vec[Str] = Vec[Str].new();
  l3_highs.push("Recursion"); l3_highs.push("Option & Result"); l3_highs.push("Error Handling");
  journey.push(LevelSummary{ level: Level.L3, name: "Advanced Types", lessons: 40, highlights: l3_highs });

  let mut l4_highs: Vec[Str] = Vec[Str].new();
  l4_highs.push("Contracts"); l4_highs.push("Structs"); l4_highs.push("Enums"); l4_highs.push("Match");
  journey.push(LevelSummary{ level: Level.L4, name: "Data Modeling", lessons: 40, highlights: l4_highs });

  let mut l5_highs: Vec[Str] = Vec[Str].new();
  l5_highs.push("Ownership"); l5_highs.push("Borrowing"); l5_highs.push("References");
  journey.push(LevelSummary{ level: Level.L5, name: "Memory Management", lessons: 40, highlights: l5_highs });

  let mut l6_highs: Vec[Str] = Vec[Str].new();
  l6_highs.push("Vec & Map"); l6_highs.push("Generics"); l6_highs.push("Interfaces");
  journey.push(LevelSummary{ level: Level.L6, name: "Collections & Generics", lessons: 40, highlights: l6_highs });

  let mut l7_highs: Vec[Str] = Vec[Str].new();
  l7_highs.push("Modules"); l7_highs.push("Capstone Suite"); l7_highs.push("Complex Apps");
  journey.push(LevelSummary{ level: Level.L7, name: "Mastery", lessons: 40, highlights: l7_highs });

  let mut l8_highs: Vec[Str] = Vec[Str].new();
  l8_highs.push("Snake Game"); l8_highs.push("Chess Board"); l8_highs.push("RPG Builder");
  l8_highs.push("Weather Dashboard"); l8_highs.push("Morse Code"); l8_highs.push("Full Applications");
  journey.push(LevelSummary{ level: Level.L8, name: "Ecosystem", lessons: 20, highlights: l8_highs });

  journey
}
```

### Favorite Programs

```xiom
type Favorite {
  name: Str;
  reason: Str;
  concepts_used: Vec[Str];
}

fn list_favorites() -> Vec[Favorite] {
  let mut favs: Vec[Favorite] = Vec[Favorite].new();

  let mut c1: Vec[Str] = Vec[Str].new();
  c1.push("loops"); c1.push("conditionals"); c1.push("random"); c1.push("game-state");
  favs.push(Favorite{ name: "Number Guessing Game", reason: "Your first real game — a player vs. the computer", concepts_used: c1 });

  let mut c2: Vec[Str] = Vec[Str].new();
  c2.push("structs"); c2.push("enums"); c2.push("pattern-matching"); c2.push("narrative");
  favs.push(Favorite{ name: "Text Adventure", reason: "You built an interactive world with choices and consequences", concepts_used: c2 });

  let mut c3: Vec[Str] = Vec[Str].new();
  c3.push("contracts"); c3.push("structs"); c3.push("transactions"); c3.push("invariant");
  favs.push(Favorite{ name: "Bank Account Simulator", reason: "Code with mathematical guarantees — money never vanishes", concepts_used: c3 });

  let mut c4: Vec[Str] = Vec[Str].new();
  c4.push("vec"); c4.push("grid"); c4.push("collision"); c4.push("game-loop"); c4.push("rendering");
  favs.push(Favorite{ name: "Snake Game", reason: "The most complex program in the curriculum — and you built it", concepts_used: c4 });

  favs
}
```

