### The Diploma

```xiom
fn print_diploma() {
  let stats = compute_stats();
  let skills = list_skills();
  let favorites = list_favorites();
  let journey = build_journey();

  io.println("DIPLOMA");
  io.println("XIOM Programming");

  let total = stats.0;
  io.println(total);
  io.println(stats.1);
  io.println(stats.2);

  io.println("SKILLS MASTERED:");
  let mut si = 0;
  while si < skills.len() {
    io.println(skills.get(si).unwrap());
    si += 1;
  };

  io.println("FAVORITE PROGRAMS:");
  let mut fi = 0;
  while fi < favorites.len() {
    let fav = favorites.get(fi).unwrap();
    io.println(fav.name);
    fi += 1;
  };

  io.println("JOURNEY:");
  let mut ji = 0;
  while ji < journey.len() {
    let lev = journey.get(ji).unwrap();
    io.println(lev.name);
    io.println(lev.lessons);
    ji += 1;
  };
}
```

### The Final Message

```xiom
fn closing_message() {
  io.println("This isn't the end. It's the beginning.");
  io.println("You are a programmer. Welcome to the club.");
  io.println("Go build something amazing.");
}
```

